    $$(".invoice-print").forEach(b=>b.onclick=()=>{const i=(invoices||[]).find(x=>x.id===b.dataset.id);if(!i)return;const age=ageFromBirthDate(i.customers?.birth_date);const m=modal("Detalle de cobro",`<div class="voucher-sheet"><div class="voucher" style="max-width:520px;margin:auto"><h4>ROOM ISP</h4><small>Detalle interno de cobranza</small><div style="text-align:left;margin-top:16px"><b>Cliente</b><div>${esc(i.customers?.full_name||"—")}</div><b>Documento</b><div>${esc(i.customers?.document_type||"")} ${esc(i.customers?.document_number||"—")}${age==null?"":` · ${age} años`}</div><b>Periodo</b><div>${fmtDate(i.period_start)} → ${fmtDate(i.period_end)}</div><b>Vencimiento</b><div>${fmtDate(i.due_date)}</div><b>Total</b><div>${fmtMoney(i.total)}</div><b>Saldo</b><div>${fmtMoney(i.balance)}</div><b>Estado</b><div>${esc(i.status)}</div></div></div></div><div class="form-actions no-print"><button type="button" class="btn primary" id="print-invoice">${icon("printer")} Imprimir</button></div>`,null);$("#print-invoice",m).onclick=()=>window.print();hydrate()});
    $("#generate-invoices").onclick=async e=>{e.currentTarget.disabled=true;try{const r=await D.api("isp_generate_invoices",{organization_id:oid});toast(`${r.generated||0} facturas generadas`,"success");await renderBilling(oid)}catch(err){toast(errorText(err),"error");e.currentTarget.disabled=false}};
