    $$(".ticket-open").forEach(b=>b.onclick=()=>openTicket(oid,b.dataset.id));$$(".request-review").forEach(b=>b.onclick=()=>modal(b.dataset.approve==="1"?"Aprobar solicitud":"Rechazar solicitud",`<div class="notice ${b.dataset.approve==="1"?"info":"warn"}">${b.dataset.approve==="1"?"Si es un cambio de plan, se enviará la orden al MikroTik.":"La solicitud quedará rechazada y no se ejecutará ningún cambio."}</div>`,async()=>{await D.api("isp_review_customer_request",{organization_id:oid,request_id:b.dataset.id,approve:b.dataset.approve==="1"});await renderSupport(oid)},{submitLabel:b.dataset.approve==="1"?"Aprobar":"Rechazar"}));hydrate();
